#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

struct Fenwick {
    int n;
    vector<int> tree;
    Fenwick(int n) : n(n), tree(n + 1, 0) {}
    void add(int i, int delta) {
        for (; i <= n; i += i & -i) tree[i] += delta;
    }
    int query(int i) {
        int sum = 0;
        for (; i > 0; i -= i & -i) sum += tree[i];
        return sum;
    }
};

struct Point {
    long long u, v;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    long long x1, x2;
    if (!(cin >> n >> x1 >> x2)) return 0;

    vector<Point> pts(n);
    vector<long long> all_v(n);

    for (int i = 0; i < n; ++i) {
        long long a, b;
        cin >> a >> b;
        pts[i].u = a * x1 + b;
        pts[i].v = a * x2 + b;
        all_v[i] = pts[i].v;
    }

    // Compressão de coordenadas para v
    sort(all_v.begin(), all_v.end());
    all_v.erase(unique(all_v.begin(), all_v.end()), all_v.end());

    // Ordena pontos por u
    sort(pts.begin(), pts.end(), [](const Point& p1, const Point& p2) {
        if (p1.u != p2.u) return p1.u < p2.u;
        return p1.v < p2.v;
    });

    Fenwick bit(all_v.size());
    long long concordant_pairs = 0;

    int i = 0;
    while (i < n) {
        int j = i;
        while (j < n && pts[j].u == pts[i].u) {
            j++;
        }
        // Para cada elemento no grupo com mesmo u, conta quantos elementos anteriores têm v estritamente menor
        for (int k = i; k < j; ++k) {
            // Rank de pts[k].v (1-based)
            int rank_v = lower_bound(all_v.begin(), all_v.end(), pts[k].v) - all_v.begin() + 1;
            // Queremos v estritamente menor, então consultamos rank_v - 1
            concordant_pairs += bit.query(rank_v - 1);
        }
        // Agora insere todos os elementos deste grupo na BIT
        for (int k = i; k < j; ++k) {
            int rank_v = lower_bound(all_v.begin(), all_v.end(), pts[k].v) - all_v.begin() + 1;
            bit.add(rank_v, 1);
        }
        i = j;
    }

    long long total_pairs = (1LL * n * (n - 1)) / 2;
    long long ans = total_pairs - concordant_pairs;

    cout << ans << "\n";

    return 0;
}
